ALTER TABLE public.email_message_attachments ADD COLUMN IF NOT EXISTS content_id text;
CREATE POLICY department_enquiries_modify ON public.email_enquiries FOR UPDATE TO authenticated USING ((mailbox_address IN ('accounts@imtsolutions.co.zw','billing@imtsolutions.co.zw') AND public.has_role(auth.uid(),'finance'::public.app_role)) OR (mailbox_address IN ('support@imtsolutions.co.zw','helpdesk@imtsolutions.co.zw') AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role::text IN ('technical_support','cloud_engineer','cyber_security','noc')))) WITH CHECK ((mailbox_address IN ('accounts@imtsolutions.co.zw','billing@imtsolutions.co.zw') AND public.has_role(auth.uid(),'finance'::public.app_role)) OR (mailbox_address IN ('support@imtsolutions.co.zw','helpdesk@imtsolutions.co.zw') AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role::text IN ('technical_support','cloud_engineer','cyber_security','noc'))));